mapper.select:
     SELECT * FROM (
        SELECT 
        	ci2.RCP_SEQ AS top1_rcp_seq,
        	r2.RCP_NM AS top1_nm,
        	COUNT(ci2.RCP_SEQ) AS top1_count
        FROM CALENDAR_ITEM ci2
        JOIN RECIPE r2 ON ci2.RCP_SEQ = r2.RCP_SEQ
        WHERE ci2.user_id = #{user_id}
	      AND TO_CHAR(ci2.meal_date, 'YYYY') = #{year}
	      AND TO_CHAR(ci2.meal_date, 'MM') = #{month} 
        GROUP BY ci2.RCP_SEQ, r2.RCP_NM
        ORDER BY top1_count DESC
    ) WHERE ROWNUM = 1

mapper.delete:
DELETE FROM CALENDAR_ITEM 
WHERE user_id = #{user_id}
  AND TRUNC(meal_date) = TO_DATE(#{meal_date}, 'YYYY-MM-DD')
  AND meal_type = #{meal_type}
